mapper.select:
SELECT COALESCE(SUM(t2.weight),0) as weight, COUNT(t2.id) as slices FROM meattrade_pork_report t1 LEFT JOIN meattrade_pork_arrange_detail t2 on t1.id = t2.pork_report_id
t1.tenant = #{param.tenant} AND t2.tenant = #{param.tenant} AND t1.`status` IN ('PASSED','FAILED')
and t1.create_time >= #{param.period.begin}
and t1.create_time <= #{param.period.end}

SELECT COUNT(DISTINCT t1.supplier_id) as supplier_count FROM meattrade_pork_report t1
t1.tenant = #{param.tenant} AND t1.`status` IN ('PASSED','FAILED')
and t1.create_time >= #{param.period.begin}
and t1.create_time <= #{param.period.end}
